-- GENERATED by `wfj generate` from data/gossip/gossip-8d.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["8d0011cae2ff9d0b"] = { "Ce ne andremo da qui non appena avrò riparato questo carro. . . .", "." },
  ["8d04627dc4dfcd7d"] = { "Non farmi arrabbiare! Non ti piacerei quando perdo le staffe!", "." },
  ["8d08eeb3a7cf5359"] = { "Va' nel ⟦Mage Quarter=Quartiere dei Maghi⟧ e cerca Fyrenz Stargazer, appena a nord-ovest della torre dei maghi.", "." },
  ["8d09afb1cbeece18"] = { "Hai trovato una chiave? Beh, è LA chiave? Voglio dire, è la chiave che apre queste catene? Beh, <signore/signora>, c'è un solo modo per scoprirlo!", "." },
  ["8d0ad33c2d8957f7"] = { "Questo dovrebbe alleviare il dolore.", "." },
  ["8d1489be8694d3bc"] = { "Ho perso la mia ⟦Zandalar Illusionist's Robe=Tonaca dell'Illusionista degli Zandalari⟧ e me ne serve una nuova, Al'tabim.", "." },
  ["8d1b949539ae99b7"] = { "Ho scoperto un uso per il carapace del ragno delle cripte e per le varie parti del suo corpo. Combinando i frammenti con alcune delle armature magiche profanate perdute a Naxxramas, riesco a forgiare un'armatura leggerissima e assai letale.", "." },
  ["8d21b0012e802784"] = { "<Benvenuto/Benvenuta> alla Banca di ⟦Stormwind=Roccavento⟧. Offriamo conti finanziari e cassette di sicurezza per gli oggetti di valore. Hai già un conto presso di noi, <signore/signora>?", "." },
  ["8d221ae3cc4d5010"] = { "Le tue abilità stanno progredendo bene. Presto gestirai una bottega di pelletteria tutta tua. Mi farà piacere avere un aiuto, {name}. Le mie mani hanno un limite di velocità, sai? C'è così tanto lavoro da fare!", "." },
  ["8d24ffc7c70840fd"] = { "Bene... bene, A-Me. A-Me fa bene. Casa. Trova casa.", "." },
  ["8d3a1a168e6c86b9"] = { "Pensi di aver vinto? Così facilmente? La legione ha appena iniziato la sua marcia. Gli eserciti di C'thun raderanno al suolo questo mondo.", "." },
  ["8d3a1b6dcb212630"] = { "Ascoltatemi, abitanti del Cratere! Vengo a purificare col fuoco questa terra dalla sua impurità!", "." },
  ["8d42be5d61bd660b"] = { "Per la forza della terra, il potere delle tempeste e...", "." },
  ["8d4435cec73bff6e"] = { "Su %s sono sparse ossa rotte e briciole di cracker.", "." },
  ["8d466e4f1d3f75e8"] = { "Ce l'abbiamo fatta, <ragazzo/ragazza>! L'⟦Alliance=Alleanza⟧ e l'⟦Horde=Orda⟧ hanno finito di raccogliere tutto ciò che pensiamo ci servirà per la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. In questo momento le ultime merci vengono portate alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e arriveranno tutte entro $2113w giorni. Dopodiché, <un/una> <eroe/eroina> <coraggioso/coraggiosa> dovrà suonare lo Scarab Gong con lo Scepter of the Shifting Sands per aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Quando quei cancelli si apriranno, la guerra avrà inizio!", "." },
  ["8d562c0845f0c772"] = { "Perché mi guardi così? Ti aspetti che ti scagli contro dei fulmini, o che ti minacci con l'ira del Signore del Vento?\r\n\nSe è così, ci sta. Però non tutti noi siamo così... zelanti.", "." },
  ["8d5907c031603d3a"] = { "Quale campo di battaglia tu vuoi?", "." },
  ["8d63c8d1168e246a"] = { "Mmm, questa buona idea. Forse noi andiamo là per farci sostituire qualche punto? Lui cuce bene. Tu trova Josef Gregorian in cerchio interno di ⟦Magic Quarter=Quartiere della Magia⟧.", "." },
  ["8d65d7c97e8a10ec"] = { "È vero, anche lo stranglekelp può essere molto utile per accumulare ciò che ci serve per la prossima guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧! Ha così tanti usi: per fare il gelato nelle giornate calde sotto il sole di ⟦Silithus=Silitus⟧, come unguento contro gli effetti di certe piante schifose, per respirare sott'acqua, indurire la pelle, renderti più veloce, recuperare il potere magico; così tante cose che non me le ricordo tutte! Ti ho detto del gelato?\n\nInsomma, qui ne ho circa $2047w, e me ne servono $2048w in tutto!", "." },
  ["8d6a96d6f03815c6"] = { "Cos'è stato? Hai lasciato acceso quel razzo?!", "." },
  ["8d6adab82d8fca12"] = { "Un lingotto di Sulfuron?!??! Impossibile! Devo averlo! Devo! Devo!\n\n{race}, ho l'autorizzazione per proporti un affare grandioso per quel lingotto. Forse ti interesserebbe conoscere i segreti del ⟦Hand of Ragnaros=Pugno di Ragnaros⟧? Sulfuras, idiota! Il leggendario martello del Signore del Fuoco.", "." },
  ["8d70e317eb545ca9"] = { "Tu guarda in The Apothecarium. Là dottor Herbert Halsey e dottor Marsh lavorano.", "." },
  ["8d75d4c30b9c0c88"] = { "Ha preso il pettorale runico non forgiato, che serve a fabbricare il Pettorale Corazzato Forgiato dal Demone, ed è scappato senza pagare. Però non mi faccio fregare così facilmente... il pezzo non forgiato è inutile senza la conoscenza, o la ricetta per applicare tale conoscenza.\n\nMi chiedo... se ne sta al sicuro nella sua città, i ⟦Blackrock Spire=Bastioni di Roccianera⟧, cercando di creare l'oggetto dalla materia grezza? So che non osa andarsene!", "." },
  ["8d7afbc21c9e43dc"] = { "Al'tabim, le mie ⟦Zandalar Confessor's Wraps=Polsiere del Confessore degli Zandalari⟧ sono sparite. Puoi sostituirmele?", "." },
  ["8d7f630facc2eee6"] = { "Hai cominciato bene, ma hai ancora molto da imparare, {name}.", "." },
  ["8d8086eeb6584322"] = { "Mmm, be', vedo che hai una certa abilità nel preparare pozioni. Resta da vedere, però, se sei <degno/degna> di essere <mio/mia> <allievo/allieva>. Ho un lavoro per te. Stupiscimi.", "." },
  ["8d8e71af19d9a3b3"] = { "<Benvenuto/Benvenuta> al ⟦Cenarion Circle=Circolo Cenariano⟧, {class}. Come posso aiutarti?", "." },
  ["8d91e72250f95932"] = { "<Stolto/Stolta> {class}! Non sei all'altezza dei servitori di Ragnaros!", "." },
  ["8d966e33c3a02850"] = { "Sono qui! Vieni ad affrontarmi, se hai il coraggio!", "." },
  ["8d9d5108207d90b6"] = { "Ti serve addestramento? Beh, Azar Stronghammer è sempre pronto a mostrare un paio di cose ai paladini più giovani. Perché non vai a trovarlo alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧?", "." },
  ["8da64a9b4a6f40cd"] = { "Ti consegnerò all'aldilà, debole {class}!", "." },
  ["8dad0d1980b5b5fb"] = { "Pochissimi vengono a cercarmi... Cosa posso fare per te?", "." },
  ["8dae7099749d21a3"] = { "Ti prego.", "." },
  ["8db761e6dc39b029"] = { "Certi avventurieri pensano che l'incantamento non funzioni. Ho notato che quando li sfido a battaglia cambiano subito musica!", "." },
  ["8dbb03fccb017b63"] = { "A cosa servono quelle casse?", "." },
  ["8dc0f925464aa4ff"] = { "In preda a cosa?", "." },
  ["8dce57af5b58dc6c"] = { "⟦Blackrock Spire=Bastioni di Roccianera⟧", "." },
  ["8dd16d39e7857c93"] = { "Raccontami di nuovo dei cimiteri...", "." },
  ["8dd1a4b3e11125f4"] = { "La ⟦The League of Arathor=Lega di Arathor⟧ ha giurato di riconquistare Arathi per gli umani di Stromgarde e per l'⟦Alliance=Alleanza⟧. È una battaglia dura, ma una battaglia per cui vale la pena combattere.", "." },
  ["8dd5e6f65e220b8b"] = { "Falthir, ho bisogno di aiuto per sostituire un pezzo della mia Armatura del Predatore.", "." },
  ["8ddb398f029c38fb"] = { "Sia lodata la Regina delle Banshee, non capita spesso di ricevere visite qui fuori.", "." },
  ["8ddccce3ffbd9276"] = { "Beh, da quello che ho capito mentre aspettavo che questi zoticoni mi mangiassero... potrebbe non essere necessario uccidere tutti gli ogre che trovi qui.\n\nL'altro giorno gli ogre non la finivano più di raccontare come re Gordok fosse salito al potere: in pratica, aveva ucciso il re precedente e ne aveva preso il posto. Ebbene, gli scagnozzi del re, quelli che Gordok aveva risparmiato, giurarono subito fedeltà al nuovo re.\n\nChissà, l'ogre che risparmi potrebbe benissimo diventare il tuo... in senso figurato, s'intende!", "." },
  ["8ded061ce47472ba"] = { "Difensori del ⟦Darrowshire=Borgo di Darrow⟧! Raccoglietevi! Dobbiamo prevalere!", "." },
  ["8df3bdeeba7a9dc3"] = { "Quanto vorrei unirmi a te nella gloriosa battaglia, ma il dovere mi tiene qui. Va' alla Hall of the Brave, nella ⟦Valley of Honor=Valle dell'Onore⟧ di Orgrimmar, e parla con Kartra Bloodsnarl. Ti aiuterà a raggiungere la ⟦Alterac Valley=Valle d'Alterac⟧. Rendici orgogliosi, {name}!", "." },
  ["8df4729ed1d72ebf"] = { "%s comincia a evocare spettri dall'aria gelida!", "." },
  ["8df4996b49c0520e"] = { "Non di nuovo...", "." },
  ["8df81e2d4377059d"] = { "%s segue felice {name}: ora è il suo nuovo germoglio.", "." },
})
